package kr.memorynotes;
import android.app.*;import android.graphics.Color;import android.text.*;import android.text.style.*;import android.view.*;import android.widget.*;import org.json.*;
final class ColorText {
 static final String[] NAMES={"빨강","주황","초록","파랑","보라","기본색으로 되돌리기"};
 static final int[] COLORS={0xFFE76F78,0xFFDC9346,0xFF57A889,0xFF669FEE,0xFFAD83D6};
 static class Tint extends CharacterStyle implements UpdateAppearance {final int color;Tint(int c){color=c;}public void updateDrawState(TextPaint p){p.setColor(color);}}
 static JSONArray ranges(Note n,String key){JSONArray r=n.textColors.optJSONArray(key);return r==null?new JSONArray():r;}
 static void store(Note n,String key,JSONArray ranges){try{n.textColors.put(key,ranges);}catch(JSONException e){throw new IllegalStateException(e);}}
 static void apply(Spannable text,JSONArray ranges){for(Tint s:text.getSpans(0,text.length(),Tint.class))text.removeSpan(s);for(int i=0;i<ranges.length();i++){JSONObject r=ranges.optJSONObject(i);if(r==null)continue;int start=Math.max(0,r.optInt("start")),end=Math.min(text.length(),r.optInt("end"));if(end>start)text.setSpan(new Tint(r.optInt("color")),start,end,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}}
 static void collect(Note n,String key,EditText field){Editable t=field.getText();JSONArray out=new JSONArray();for(Tint span:t.getSpans(0,t.length(),Tint.class))ColorRanges.add(out,t.getSpanStart(span),t.getSpanEnd(span),span.color);store(n,key,out);}
 static void bind(MainActivity a,Note n,String key,EditText field,Runnable changed,boolean ownMenu){field.setTag("ink:"+key);if(android.os.Build.VERSION.SDK_INT>=33)field.setAutoHandwritingEnabled(false);apply(field.getText(),ranges(n,key));field.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int st,int c,int af){}public void onTextChanged(CharSequence s,int st,int before,int count){}public void afterTextChanged(Editable text){refresh(text);collect(n,key,field);}});if(ownMenu)field.setCustomSelectionActionModeCallback(new ActionMode.Callback(){public boolean onCreateActionMode(ActionMode m,Menu menu){menu.add(0,903,2,"글자색");return true;}public boolean onPrepareActionMode(ActionMode m,Menu menu){return false;}public boolean onActionItemClicked(ActionMode m,MenuItem item){if(item.getItemId()!=903)return false;choose(a,n,key,field,changed);m.finish();return true;}public void onDestroyActionMode(ActionMode m){}});}
 static void refresh(Editable t){for(Tint span:t.getSpans(0,t.length(),Tint.class)){int s=t.getSpanStart(span),e=t.getSpanEnd(span);t.removeSpan(span);if(e>s)t.setSpan(span,s,e,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}}
 static void choose(MainActivity a,Note n,String key,EditText field,Runnable changed){int start=Math.min(field.getSelectionStart(),field.getSelectionEnd()),end=Math.max(field.getSelectionStart(),field.getSelectionEnd());if(start<0||end<=start){a.u.message("먼저 색을 바꿀 글자를 길게 눌러 블록으로 선택하세요.");return;}new AlertDialog.Builder(a).setTitle("선택한 글자색").setItems(NAMES,(d,which)->{collect(n,key,field);JSONArray updated=ColorRanges.replace(ranges(n,key),start,end,which<COLORS.length?COLORS[which]:null);store(n,key,updated);apply(field.getText(),updated);field.invalidate();changed.run();}).show();}
 static void append(SpannableStringBuilder out,JSONArray ranges,int sourceStart,int sourceEnd,int outputStart){for(int i=0;i<ranges.length();i++){JSONObject r=ranges.optJSONObject(i);if(r==null)continue;int start=Math.max(sourceStart,r.optInt("start")),end=Math.min(sourceEnd,r.optInt("end"));if(end>start)out.setSpan(new Tint(r.optInt("color")),outputStart+start-sourceStart,outputStart+end-sourceStart,Spanned.SPAN_EXCLUSIVE_EXCLUSIVE);}}
 static void replaceText(EditText e,String value){String old=e.getText().toString();int from=0;while(from<old.length()&&from<value.length()&&old.charAt(from)==value.charAt(from))from++;int oldEnd=old.length(),newEnd=value.length();while(oldEnd>from&&newEnd>from&&old.charAt(oldEnd-1)==value.charAt(newEnd-1)){oldEnd--;newEnd--;}e.getText().replace(from,oldEnd,value.substring(from,newEnd));}
}
